from z3 import *

def solve_qg3(n):
    s = Solver()
    # Use a 2D array of Ints
    x = [[Int(f"x_{i}_{j}") for j in range(n)] for i in range(n)]

    # Latin square
    for i in range(n):
        s.add(Distinct(x[i]))
        s.add(Distinct([x[j][i] for j in range(n)]))
        for j in range(n):
            s.add(x[i][j] >= 0, x[i][j] < n)

    # Idempotent
    for i in range(n):
        s.add(x[i][i] == i)

    # QG3 property: x[x[i][j]][x[j][i]] = i
    # We need to express x[x[i][j]][x[j][i]] = i
    # Since Z3 doesn't allow variable indexing, we can use a helper:
    # For each i, j, let k = x[i][j] and l = x[j][i].
    # Then x[k][l] = i.
    # We can use If-Then-Else or a constraint that says:
    # For all i, j, k, l: (x[i][j] == k AND x[j][i] == l) => x[k][l] == i

    for i in range(n):
        for j in range(n):
            for k in range(n):
                for l in range(n):
                    s.add(Implies(And(x[i][j] == k, x[j][i] == l), x[k][l] == i))

    if s.check() == sat:
        m = s.model()
        res = []
        for i in range(n):
            for j in range(n):
                res.append(m[x[i][j]].as_long())
        return res
    else:
        return None

