from pysat.solvers import Glucose3

def solve_qg3_pysat(n):
    # Variables: x_{i,j,v} is true if x[i][j] = v
    # i, j, v in 0..n-1
    # Total variables: n*n*n = 7*7*7 = 343

    def var(i, j, v):
        return i * n * n + j * n + v + 1

    s = Glucose3()

    # Each cell has exactly one value
    for i in range(n):
        for j in range(n):
            s.add_clause([var(i, j, v) for v in range(n)])
            for v1 in range(n):
                for v2 in range(v1 + 1, n):
                    s.add_clause([-var(i, j, v1), -var(i, j, v2)])

    # Latin square: each row has each value once
    for i in range(n):
        for v in range(n):
            s.add_clause([var(i, j, v) for j in range(n)])
            for j1 in range(n):
                for j2 in range(j1 + 1, n):
                    s.add_clause([-var(i, j1, v), -var(i, j2, v)])

    # Latin square: each column has each value once
    for j in range(n):
        for v in range(n):
            s.add_clause([var(i, j, v) for i in range(n)])
            for i1 in range(n):
                for i2 in range(i1 + 1, n):
                    s.add_clause([-var(i1, j, v), -var(i2, j, v)])

    # Idempotent: x[i][i] = i
    for i in range(n):
        s.add_clause([var(i, i, i)])

    # QG3: x[x[i][j]][x[j][i]] = i
    # x[i][j] = k, x[j][i] = l => x[k][l] = i
    # For all i, j, k, l:
    # (x[i][j] == k AND x[j][i] == l) => x[k][l] == i
    # Equivalent to:
    # NOT (x[i][j] == k AND x[j][i] == l) OR x[k][l] == i
    # -var(i, j, k) OR -var(j, i, l) OR var(k, l, i)

    for i in range(n):
        for j in range(n):
            for k in range(n):
                for l in range(n):
                    s.add_clause([-var(i, j, k), -var(j, i, l), var(k, l, i)])

    if s.solve():
        model = s.get_model()
        res = [0] * (n * n)
        for i in range(n):
            for j in range(n):
                for v in range(n):
                    if model[var(i, j, v) - 1] > 0:
                        res[i * n + j] = v
        return res
    else:
        return None

